# 流式响应实现
@router.get("/deep-research/stream")
async def deep_research_stream(query: str, symbol: str):
    async def generate():
        try:
            # 发送开始信号
            yield f"data: {json.dumps({'type': 'start', 'progress': 0})}

"

            # 并行执行研究
            research_task = asyncio.create_task(
                parallel_research_engine.research_parallel(query, symbol)
            )

            # 定期发送进度更新
            while not research_task.done():
                progress_data = {
                    "type": "progress",
                    "progress": 50,  # 基于实际进度计算
                    "message": f"Analyzing {symbol}..."
                }
                yield f"data: {json.dumps(progress_data)}

"
                await asyncio.sleep(2)

            # 发送最终结果
            result = await research_task
            yield f"data: {json.dumps({'type': 'complete', 'data': result})}

"

        except Exception as e:
            yield f"data: {json.dumps({'type': 'error', 'message': str(e)})}

"

    return StreamingResponse(generate(), media_type="text/event-stream")
